  `exp_date` date DEFAULT NULL,
  `delivery_time` varchar(100) DEFAULT NULL,
  `container_status` varchar(100) DEFAULT NULL,
  `booking_status` varchar(100) DEFAULT NULL,
  `arrived_date` date DEFAULT NULL,
  `external_container_number` varchar(255) DEFAULT NULL,
  `order_cbm` decimal(10,3) DEFAULT NULL,
  `port` varchar(255) DEFAULT NULL,
  `carton_cbm` decimal(10,6) DEFAULT NULL,
  `units_per_carton` int DEFAULT NULL,
  `pack_size` varchar(100) DEFAULT NULL,
  `scheduled_date` date DEFAULT NULL,
  `po_date` date DEFAULT NULL,
  `qc_status` varchar(100) DEFAULT NULL,
  `qc_date` date DEFAULT NULL,
  `qc_invoice_number` varchar(100) DEFAULT NULL,
  `purchase_order_id` int DEFAULT NULL,
  `unit_price` decimal(10,4) DEFAULT NULL,
  `actual_ready_date` date DEFAULT NULL,
  `estimated_departure_date` date DEFAULT NULL,
  `shipped_date` date DEFAULT NULL,
  `ordered_date` date DEFAULT NULL,
  `estimated_ready_date` date DEFAULT NULL,
  `artwork_confirmed_date` date DEFAULT NULL,
  `awb_number` varchar(50) DEFAULT NULL,
  `carton_weight` decimal(10,3) DEFAULT NULL,
  `carton_height` decimal(10,3) DEFAULT NULL,
  `carton_width` decimal(10,3) DEFAULT NULL,
  `carton_depth` decimal(10,3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
