CREATE TABLE IF NOT EXISTS `purchase_order_invoice_checks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `purchase_order_invoice_id` int NOT NULL,
  `status` enum('pending','succeeded','failed') NOT NULL,
  `verdict` varchar(32) DEFAULT NULL,
  `discrepancy_count` int DEFAULT NULL,
  `result_json` json DEFAULT NULL,
  `model_used` varchar(64) DEFAULT NULL,
  `input_tokens` int DEFAULT NULL,
  `output_tokens` int DEFAULT NULL,
  `total_tokens` int DEFAULT NULL,
  `error_code` varchar(64) DEFAULT NULL,
  `error_message` text,
  `triggered_by` varchar(32) DEFAULT NULL,
  `triggered_by_email` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_invoice_id` (`purchase_order_invoice_id`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `purchase_order_invoice_payments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `purchase_order_invoice_id` int NOT NULL,
  `purchase_order_id` int NOT NULL,
  `payment_type` varchar(32) DEFAULT NULL,
  `amount_due` decimal(14,2) DEFAULT NULL,
  `currency` char(3) DEFAULT NULL,
  `deposit_percentage` decimal(6,3) DEFAULT NULL,
  `invoice_total` decimal(14,2) DEFAULT NULL,
  `due_date` date DEFAULT NULL,
  `due_terms` varchar(500) DEFAULT NULL,
  `beneficiary_name` varchar(255) DEFAULT NULL,
  `bank_name` varchar(255) DEFAULT NULL,
  `bank_address` varchar(500) DEFAULT NULL,
  `account_number` varchar(100) DEFAULT NULL,
  `iban` varchar(64) DEFAULT NULL,
  `swift_bic` varchar(32) DEFAULT NULL,
  `intermediary_bank` varchar(255) DEFAULT NULL,
  `payment_reference` varchar(255) DEFAULT NULL,
  `raw_terms_text` text,
  `payment_status` enum('pending','arranged','paid','skipped') NOT NULL DEFAULT 'pending',
  `extracted_from_check_id` int DEFAULT NULL,
  `model_used` varchar(64) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_invoice` (`purchase_order_invoice_id`),
  KEY `idx_purchase_order_id` (`purchase_order_id`),
  KEY `idx_payment_status` (`payment_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

