  `warehouse_id` int NOT NULL DEFAULT '0',
  `stock_level` int NOT NULL DEFAULT '0',
  `available` int NOT NULL DEFAULT '0',
  `allocated` int NOT NULL DEFAULT '0',
  `quarantine` int NOT NULL DEFAULT '0',
